CREATE TABLE IF NOT EXISTS site_administrators (user_id VARCHAR(64) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS mail_configuration (id INTEGER PRIMARY KEY, version INTEGER NOT NULL, config_json TEXT NOT NULL, password_cipher TEXT NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS mail_daily_usage (day VARCHAR(10) PRIMARY KEY, total INTEGER NOT NULL DEFAULT 0, announcements INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS email_identities (email VARCHAR(254) PRIMARY KEY, owner VARCHAR(320) NOT NULL UNIQUE, verified_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS email_challenges (id VARCHAR(64) PRIMARY KEY, owner VARCHAR(320) NOT NULL, email VARCHAR(254) NOT NULL, purpose VARCHAR(32) NOT NULL, digest VARCHAR(64) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS mail_queue (id VARCHAR(64) PRIMARY KEY, household_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, recipient VARCHAR(254) NOT NULL, kind VARCHAR(32) NOT NULL, payload MEDIUMTEXT NOT NULL, status VARCHAR(32) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, due_at VARCHAR(40) NOT NULL, expires_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL);

CREATE TABLE IF NOT EXISTS mail_preferences (user_id VARCHAR(64) PRIMARY KEY, announcements INTEGER NOT NULL DEFAULT 1);
